function New-Server([string]$name,[int]$port){if(Get-NetTCPConnection -LocalPort $port -ErrorAction SilentlyContinue|Where-Object State -ne TimeWait){throw "Port in use $port"};$root=Join-Path $OutputRoot $name;$data=Join-Path $root data;$logs=Join-Path $root logs;New-Item -ItemType Directory $data,$logs -Force|Out-Null;$ini=Join-Path $root my.ini;[IO.File]::WriteAllText($ini,@"
