"@,[Text.UTF8Encoding]::new($false));&$mysqld "--defaults-file=$ini" --initialize-insecure;if($LASTEXITCODE){throw "init failed $name"};$p=Start-Process $mysqld -ArgumentList "--defaults-file=$ini" -WindowStyle Hidden -PassThru;$script:servers+=$p;foreach($i in 1..100){$old=$ErrorActionPreference;$ErrorActionPreference='Continue';&$mysqladmin --protocol=TCP --host=127.0.0.1 --port=$port --user=root ping 2>$null|Out-Null;$c=$LASTEXITCODE;$ErrorActionPreference=$old;if(!$c){return @{Name=$name;Port=$port;Root=$root}};Start-Sleep -Milliseconds 300};throw "not ready $name"}
function DB($s,[string]$sql,[switch]$raw){$a=@('--protocol=TCP','--host=127.0.0.1',"--port=$($s.Port)",'--user=root','--database=enterprise_platform');if($raw){$a+=@('--batch','--raw','--skip-column-names')};$old=$ErrorActionPreference;$ErrorActionPreference='Continue';$o=&$mysql @a "--execute=$sql" 2>&1;$c=$LASTEXITCODE;$ErrorActionPreference=$old;@{ExitCode=$c;Output=($o-join"`n")}}
function Baseline($s){foreach($n in $baselineFiles){$f=Join-Path $baseline $n;$a=@('--protocol=TCP','--host=127.0.0.1',"--port=$($s.Port)",'--user=root','--default-character-set=utf8mb4');if($n-ne'01_database.sql'){$a+='--database=enterprise_platform'};$o=&$mysql @a "--execute=source $($f.Replace('\','/'))" 2>&1;if($LASTEXITCODE){throw "baseline $n failed $($o-join' ')"}}}
function Fly($s,[string]$loc,[string]$command,[string]$target=''){$a=@("-url=jdbc:mysql://127.0.0.1:$($s.Port)/enterprise_platform",'-user=root','-password=',"-locations=filesystem:$($loc.Replace('\','/'))",'-baselineOnMigrate=true','-baselineVersion=2.0.0','-validateMigrationNaming=true','-cleanDisabled=true','-connectRetries=10');if($target){$a+="-target=$target"};$a+=$command;$old=$ErrorActionPreference;$ErrorActionPreference='Continue';$o=&$flyway @a 2>&1;$c=$LASTEXITCODE;$ErrorActionPreference=$old;$o|Set-Content (Join-Path $evidence "$($s.Name)-$command-$([DateTime]::UtcNow.Ticks).log");@{ExitCode=$c;Output=($o-join"`n")}}
function MustFly($s,$loc,$cmd,$target=''){$r=Fly $s $loc $cmd $target;if($r.ExitCode){throw $r.Output};$r}
function Reject($s,$name,$sql,$expected=''){$r=DB $s $sql;$pass=$r.ExitCode-ne0-and(!$expected-or$r.Output.Contains($expected));Add $name $pass $r.Output}
function Fingerprint($s){$a=@('--protocol=TCP','--host=127.0.0.1',"--port=$($s.Port)",'--user=root','--database=enterprise_platform','--batch','--raw','--skip-column-names');$rows=Get-Content $fingerprintSql -Raw|&$mysql @a;$tr=&$mysql @a '--execute=SELECT CONCAT("TRIGGER|",trigger_name,"|",event_manipulation,"|",event_object_table,"|",action_timing,"|",REPLACE(REPLACE(action_statement,CHAR(13)," "),CHAR(10)," ")) FROM information_schema.triggers WHERE trigger_schema=DATABASE() ORDER BY trigger_name';$all=@($rows)+@($tr);$org=$all|Where-Object{$_-match 'approval_role|sys_org|sys_user'};$dir=$all|Where-Object{$_-match 'approval_role'};$o=@{};foreach($p in @(@('full',$all),@('organization',$org),@('directory',$dir))){$f=Join-Path $evidence "$($s.Name)-$($p[0]).txt";[IO.File]::WriteAllText($f,(($p[1]-join"`n")+"`n"),[Text.UTF8Encoding]::new($false));$o[$p[0]]=(Get-FileHash $f -Algorithm SHA256).Hash.ToLower()};$o}
function Concurrent($s,[string]$name,[string]$sql1,[string]$sql2){$i1=Join-Path $evidence "$name-1.sql";$i2=Join-Path $evidence "$name-2.sql";$o1=Join-Path $evidence "$name-1.out";$o2=Join-Path $evidence "$name-2.out";$e1=Join-Path $evidence "$name-1.err";$e2=Join-Path $evidence "$name-2.err";[IO.File]::WriteAllText($i1,$sql1,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText($i2,$sql2,[Text.UTF8Encoding]::new($false));$a=@('--protocol=TCP','--host=127.0.0.1',"--port=$($s.Port)",'--user=root','--database=enterprise_platform','--force');$p1=Start-Process $mysql -ArgumentList $a -WindowStyle Hidden -PassThru -RedirectStandardInput $i1 -RedirectStandardOutput $o1 -RedirectStandardError $e1;$p2=Start-Process $mysql -ArgumentList $a -WindowStyle Hidden -PassThru -RedirectStandardInput $i2 -RedirectStandardOutput $o2 -RedirectStandardError $e2;$p1.WaitForExit();$p2.WaitForExit();$t1=(Get-Content $e1 -ErrorAction SilentlyContinue)-join' ';$t2=(Get-Content $e2 -ErrorAction SilentlyContinue)-join' ';@{errors=@($t1,$t2).Where({$_-match'ERROR'}).Count;deadlock=("$t1 $t2"-match'ERROR 1213|ERROR 1205');text="$t1 | $t2"}}
